DROP TABLE IF EXISTS `product_browse_history`;
CREATE TABLE `product_browse_history` (
  `id`             bigint      NOT NULL AUTO_INCREMENT COMMENT '记录编号',
  `user_id`        bigint      NOT NULL COMMENT '用户编号',
