  `updater`        varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time`    datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`        bit(1)      NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_user_create_time` (`user_id`, `create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品浏览记录表';

-- >>>>>>>>>> ddl/08-trade.sql <<<<<<<<<<
-- ----------------------------------------------------------------------------
-- trade 模块：购物车、订单、售后、配送、交易配置、分销
-- 本文件由 DDL 生成器产出，公共约定与 01-system.sql 一致
-- ----------------------------------------------------------------------------
USE `ccloud`;

-- ========================= 配置 =========================

DROP TABLE IF EXISTS `trade_config`;
CREATE TABLE `trade_config` (
  `id`                               bigint        NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `after_sale_refund_reasons`        varchar(2000) DEFAULT NULL COMMENT '售后退款理由数组',
  `after_sale_return_reasons`        varchar(2000) DEFAULT NULL COMMENT '售后退货理由数组',
  `delivery_express_free_enabled`    bit(1)        NOT NULL DEFAULT b'0' COMMENT '是否启用全场包邮',
  `delivery_express_free_price`      int           NOT NULL DEFAULT 0 COMMENT '全场包邮最小金额，单位：分',
  `delivery_pick_up_enabled`         bit(1)        NOT NULL DEFAULT b'0' COMMENT '是否开启自提',
  `brokerage_enabled`                bit(1)        NOT NULL DEFAULT b'1' COMMENT '是否启用分佣',
  `brokerage_enabled_condition`      tinyint       NOT NULL DEFAULT 1 COMMENT '分佣模式：1 人人分销 2 指定分销',
  `brokerage_bind_mode`              tinyint       NOT NULL DEFAULT 1 COMMENT '分销关系绑定模式：1 首次绑定 2 注册绑定 3 覆盖绑定',
  `brokerage_poster_urls`            varchar(2000) DEFAULT '' COMMENT '分销海报图地址数组',
  `brokerage_first_percent`          int           NOT NULL DEFAULT 0 COMMENT '一级返佣比例，百分比',
  `brokerage_second_percent`         int           NOT NULL DEFAULT 0 COMMENT '二级返佣比例，百分比',
  `brokerage_withdraw_min_price`     int           NOT NULL DEFAULT 0 COMMENT '用户提现最低金额，单位：分',
  `brokerage_withdraw_fee_percent`   int           NOT NULL DEFAULT 0 COMMENT '提现手续费百分比',
  `brokerage_frozen_days`            int           NOT NULL DEFAULT 7 COMMENT '佣金冻结天数，过售后期才可提现',
  `brokerage_withdraw_types`         varchar(32)   NOT NULL DEFAULT '' COMMENT '提现方式数组',
  `tenant_id`                        bigint        NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`                          varchar(64)   DEFAULT '' COMMENT '创建者',
  `create_time`                      datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`                          varchar(64)   DEFAULT '' COMMENT '更新者',
  `update_time`                      datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`                          bit(1)        NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='交易中心配置表，每个租户一条';

-- ========================= 购物车 =========================

DROP TABLE IF EXISTS `trade_cart`;
CREATE TABLE `trade_cart` (
  `id`            bigint      NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id`       bigint      NOT NULL COMMENT '用户编号',
  `spu_id`        bigint      NOT NULL COMMENT '商品 SPU 编号',
  `sku_id`        bigint      NOT NULL COMMENT '商品 SKU 编号',
  `count`         int         NOT NULL COMMENT '商品购买数量',
  `selected`      bit(1)      NOT NULL DEFAULT b'1' COMMENT '是否选中',
  `tenant_id`     bigint      NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`       varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time`   datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`       varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time`   datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       bit(1)      NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  UNIQUE KEY `uk_user_sku` (`user_id`, `sku_id`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='购物车表';

-- ========================= 订单 =========================

DROP TABLE IF EXISTS `trade_order`;
CREATE TABLE `trade_order` (
  `id`                            bigint       NOT NULL AUTO_INCREMENT COMMENT '订单编号',
  `no`                            varchar(64)  NOT NULL COMMENT '订单流水号',
  `type`                          tinyint      NOT NULL DEFAULT 0 COMMENT '订单类型：0 普通 1 秒杀 2 砍价 3 拼团 4 积分',
  `terminal`                      tinyint      NOT NULL COMMENT '订单来源终端',
  `user_id`                       bigint       NOT NULL COMMENT '用户编号',
  `user_ip`                       varchar(30)  NOT NULL COMMENT '用户 IP',
  `user_remark`                   varchar(200) DEFAULT NULL COMMENT '用户备注',
  `status`                        tinyint      NOT NULL DEFAULT 0 COMMENT '订单状态：0 待支付 10 待发货 20 已发货 30 已完成 40 已取消',
  `product_count`                 int          NOT NULL COMMENT '购买商品数量',
  `cancel_type`                   tinyint      DEFAULT NULL COMMENT '取消类型：10 超时未支付 20 退款关闭 30 买家取消 40 拼团关闭',
  `remark`                        varchar(200) DEFAULT NULL COMMENT '商家备注',
  `comment_status`                bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否已评价',
  `brokerage_user_id`             bigint       DEFAULT NULL COMMENT '推广人编号',
  `pay_order_id`                  bigint       DEFAULT NULL COMMENT '支付订单编号',
  `pay_status`                    bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否已支付',
  `pay_time`                      datetime     DEFAULT NULL COMMENT '付款时间',
  `pay_channel_code`              varchar(16)  DEFAULT NULL COMMENT '支付渠道',
  `finish_time`                   datetime     DEFAULT NULL COMMENT '订单完成时间',
  `cancel_time`                   datetime     DEFAULT NULL COMMENT '订单取消时间',
  `total_price`                   int          NOT NULL DEFAULT 0 COMMENT '商品原价总额，单位：分',
  `discount_price`                int          NOT NULL DEFAULT 0 COMMENT '订单优惠，单位：分',
  `delivery_price`                int          NOT NULL DEFAULT 0 COMMENT '运费金额，单位：分',
  `adjust_price`                  int          NOT NULL DEFAULT 0 COMMENT '订单调价，正数加价负数减价，单位：分',
  `pay_price`                     int          NOT NULL DEFAULT 0 COMMENT '应付金额，单位：分',
  `delivery_type`                 tinyint      NOT NULL COMMENT '配送方式：1 快递 2 自提',
  `logistics_id`                  bigint       DEFAULT NULL COMMENT '发货物流公司编号',
  `logistics_no`                  varchar(64)  DEFAULT NULL COMMENT '物流单号',
  `delivery_time`                 datetime     DEFAULT NULL COMMENT '发货时间',
  `receive_time`                  datetime     DEFAULT NULL COMMENT '收货时间',
  `receiver_name`                 varchar(20)  DEFAULT NULL COMMENT '收件人名称',
  `receiver_mobile`               varchar(20)  DEFAULT NULL COMMENT '收件人手机',
  `receiver_area_id`              int          DEFAULT NULL COMMENT '收件人地区编号',
  `receiver_detail_address`       varchar(255) DEFAULT NULL COMMENT '收件人详细地址',
  `pick_up_store_id`              bigint       DEFAULT NULL COMMENT '自提门店编号',
  `pick_up_verify_code`           varchar(64)  DEFAULT NULL COMMENT '自提核销码',
  `refund_status`                 tinyint      NOT NULL DEFAULT 0 COMMENT '售后状态：0 未申请 10 部分退款 20 全部退款',
  `refund_price`                  int          NOT NULL DEFAULT 0 COMMENT '退款金额，单位：分',
  `coupon_id`                     bigint       DEFAULT NULL COMMENT '优惠劵编号',
  `coupon_price`                  int          NOT NULL DEFAULT 0 COMMENT '优惠劵减免金额，单位：分',
  `use_point`                     int          NOT NULL DEFAULT 0 COMMENT '使用的积分',
  `point_price`                   int          NOT NULL DEFAULT 0 COMMENT '积分抵扣金额，单位：分',
  `give_point`                    int          NOT NULL DEFAULT 0 COMMENT '赠送的积分',
  `refund_point`                  int          NOT NULL DEFAULT 0 COMMENT '退还的使用积分',
  `vip_price`                     int          NOT NULL DEFAULT 0 COMMENT 'VIP 减免金额，单位：分',
  `give_coupon_template_counts`   varchar(255) DEFAULT NULL COMMENT '赠送的优惠劵，JSON',
  `give_coupon_ids`               varchar(255) DEFAULT NULL COMMENT '赠送的优惠劵编号数组',
  `seckill_activity_id`           bigint       DEFAULT NULL COMMENT '秒杀活动编号',
  `bargain_activity_id`           bigint       DEFAULT NULL COMMENT '砍价活动编号',
  `bargain_record_id`             bigint       DEFAULT NULL COMMENT '砍价记录编号',
  `combination_activity_id`       bigint       DEFAULT NULL COMMENT '拼团活动编号',
  `combination_head_id`           bigint       DEFAULT NULL COMMENT '拼团团长编号',
  `combination_record_id`         bigint       DEFAULT NULL COMMENT '拼团记录编号',
  `point_activity_id`             bigint       DEFAULT NULL COMMENT '积分商城活动编号',
  `tenant_id`                     bigint       NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`                       varchar(64)  DEFAULT '' COMMENT '创建者',
  `create_time`                   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`                       varchar(64)  DEFAULT '' COMMENT '更新者',
  `update_time`                   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`                       bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  UNIQUE KEY `uk_no` (`no`),
  KEY `idx_user_status` (`user_id`, `status`),
  KEY `idx_status_create_time` (`status`, `create_time`),
  KEY `idx_pay_order_id` (`pay_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='交易订单表';
DROP TABLE IF EXISTS `trade_order_item`;
CREATE TABLE `trade_order_item` (
  `id`                  bigint       NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id`             bigint       NOT NULL COMMENT '用户编号',
  `order_id`            bigint       NOT NULL COMMENT '订单编号',
  `cart_id`             bigint       DEFAULT NULL COMMENT '购物车项编号',
  `spu_id`              bigint       NOT NULL COMMENT '商品 SPU 编号',
  `spu_name`            varchar(255) NOT NULL DEFAULT '' COMMENT '商品名称快照',
  `sku_id`              bigint       NOT NULL COMMENT '商品 SKU 编号',
  `properties`          varchar(512) DEFAULT '' COMMENT '属性数组快照，JSON',
  `pic_url`             varchar(200) DEFAULT '' COMMENT '商品图片快照',
  `count`               int          NOT NULL COMMENT '购买数量',
  `comment_status`      bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否已评价',
  `price`               int          NOT NULL DEFAULT 0 COMMENT '商品原价，单价，单位：分',
  `discount_price`      int          NOT NULL DEFAULT 0 COMMENT '商品级优惠，总价，单位：分',
  `delivery_price`      int          NOT NULL DEFAULT 0 COMMENT '运费金额，总价，单位：分',
  `adjust_price`        int          NOT NULL DEFAULT 0 COMMENT '订单调价，总价，单位：分',
  `pay_price`           int          NOT NULL DEFAULT 0 COMMENT '子订单实付金额，总价，单位：分',
  `coupon_price`        int          NOT NULL DEFAULT 0 COMMENT '优惠劵减免金额，单位：分',
  `point_price`         int          NOT NULL DEFAULT 0 COMMENT '积分抵扣金额，单位：分',
  `use_point`           int          NOT NULL DEFAULT 0 COMMENT '使用的积分',
  `give_point`          int          NOT NULL DEFAULT 0 COMMENT '赠送的积分',
  `vip_price`           int          NOT NULL DEFAULT 0 COMMENT 'VIP 减免金额，单位：分',
  `after_sale_id`       bigint       DEFAULT NULL COMMENT '售后单编号',
  `after_sale_status`   tinyint      NOT NULL DEFAULT 0 COMMENT '售后状态：0 无 10 售后中 20 售后成功',
  `tenant_id`           bigint       NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`             varchar(64)  DEFAULT '' COMMENT '创建者',
  `create_time`         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`             varchar(64)  DEFAULT '' COMMENT '更新者',
  `update_time`         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`             bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='交易订单明细表。价格与商品信息均为下单时快照，商品改价不影响已下单';
DROP TABLE IF EXISTS `trade_order_log`;
CREATE TABLE `trade_order_log` (
  `id`              bigint        NOT NULL AUTO_INCREMENT COMMENT '日志主键',
  `user_id`         bigint        NOT NULL COMMENT '操作人编号',
  `user_type`       tinyint       NOT NULL COMMENT '操作人类型',
  `order_id`        bigint        NOT NULL COMMENT '订单编号',
  `before_status`   tinyint       DEFAULT NULL COMMENT '操作前状态',
  `after_status`    tinyint       DEFAULT NULL COMMENT '操作后状态',
  `operate_type`    int           NOT NULL COMMENT '操作类型',
  `content`         varchar(2000) NOT NULL COMMENT '操作内容',
  `tenant_id`       bigint        NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`         varchar(64)   DEFAULT '' COMMENT '创建者',
  `create_time`     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`         varchar(64)   DEFAULT '' COMMENT '更新者',
  `update_time`     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`         bit(1)        NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单操作日志表';

-- ========================= 售后 =========================

DROP TABLE IF EXISTS `trade_after_sale`;
CREATE TABLE `trade_after_sale` (
  `id`                  bigint       NOT NULL AUTO_INCREMENT COMMENT '售后编号',
  `no`                  varchar(255) NOT NULL COMMENT '售后单号',
  `type`                tinyint      DEFAULT NULL COMMENT '售后类型：10 售中 20 售后',
  `status`              tinyint      NOT NULL COMMENT '售后状态：10 申请中 20 商品待退货 30 商家待收货 40 等待退款 50 退款成功 61 买家取消 62 商家拒绝 63 商家拒收',
  `way`                 tinyint      NOT NULL COMMENT '售后方式：10 仅退款 20 退货退款',
  `user_id`             bigint       NOT NULL COMMENT '用户编号',
  `apply_reason`        varchar(255) NOT NULL COMMENT '申请原因',
  `apply_description`   varchar(255) DEFAULT NULL COMMENT '补充描述',
  `apply_pic_urls`      varchar(255) DEFAULT NULL COMMENT '补充凭证图片数组',
  `order_id`            bigint       NOT NULL COMMENT '订单编号',
  `order_no`            varchar(32)  NOT NULL COMMENT '订单流水号',
  `order_item_id`       bigint       NOT NULL COMMENT '订单项编号',
  `spu_id`              bigint       NOT NULL COMMENT '商品 SPU 编号',
  `spu_name`            varchar(255) NOT NULL COMMENT '商品 SPU 名称',
  `sku_id`              bigint       NOT NULL COMMENT '商品 SKU 编号',
  `properties`          varchar(512) DEFAULT NULL COMMENT '属性数组，JSON',
  `pic_url`             varchar(255) DEFAULT NULL COMMENT '商品图片',
  `count`               int          NOT NULL COMMENT '购买数量',
  `audit_time`          datetime     DEFAULT NULL COMMENT '审批时间',
  `audit_user_id`       bigint       DEFAULT NULL COMMENT '审批人编号',
  `audit_reason`        varchar(255) DEFAULT NULL COMMENT '审批备注',
  `refund_price`        int          NOT NULL DEFAULT 0 COMMENT '退款金额，单位：分',
  `pay_refund_id`       bigint       DEFAULT NULL COMMENT '支付退款编号',
  `refund_time`         datetime     DEFAULT NULL COMMENT '退款时间',
  `logistics_id`        bigint       DEFAULT NULL COMMENT '退货物流公司编号',
  `logistics_no`        varchar(64)  DEFAULT NULL COMMENT '退货物流单号',
  `delivery_time`       datetime     DEFAULT NULL COMMENT '退货时间',
  `receive_time`        datetime     DEFAULT NULL COMMENT '收货时间',
  `receive_reason`      varchar(255) DEFAULT NULL COMMENT '收货备注',
  `tenant_id`           bigint       NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`             varchar(64)  DEFAULT '' COMMENT '创建者',
  `create_time`         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`             varchar(64)  DEFAULT '' COMMENT '更新者',
  `update_time`         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`             bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  UNIQUE KEY `uk_no` (`no`),
  KEY `idx_order_item_id` (`order_item_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='售后订单表';
DROP TABLE IF EXISTS `trade_after_sale_log`;
CREATE TABLE `trade_after_sale_log` (
  `id`              bigint       NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id`         bigint       NOT NULL COMMENT '操作人编号',
  `user_type`       tinyint      NOT NULL COMMENT '操作人类型',
  `after_sale_id`   bigint       NOT NULL COMMENT '售后编号',
  `before_status`   tinyint      DEFAULT NULL COMMENT '售后状态（之前）',
  `after_status`    tinyint      NOT NULL COMMENT '售后状态（之后）',
  `operate_type`    int          NOT NULL COMMENT '操作类型',
  `content`         varchar(512) NOT NULL COMMENT '操作明细',
  `tenant_id`       bigint       NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`         varchar(64)  DEFAULT '' COMMENT '创建者',
  `create_time`     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`         varchar(64)  DEFAULT '' COMMENT '更新者',
  `update_time`     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`         bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_after_sale_id` (`after_sale_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='售后操作日志表';

-- ========================= 配送 =========================

DROP TABLE IF EXISTS `trade_delivery_express`;
CREATE TABLE `trade_delivery_express` (
  `id`            bigint       NOT NULL AUTO_INCREMENT COMMENT '编号',
  `code`          varchar(64)  NOT NULL COMMENT '快递公司编码',
  `name`          varchar(64)  NOT NULL COMMENT '快递公司名称',
  `logo`          varchar(256) DEFAULT NULL COMMENT '快递公司 logo',
  `sort`          int          NOT NULL DEFAULT 0 COMMENT '排序',
  `status`        tinyint      NOT NULL DEFAULT 0 COMMENT '状态：0 开启 1 关闭',
  `tenant_id`     bigint       NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`       varchar(64)  DEFAULT '' COMMENT '创建者',
  `create_time`   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`       varchar(64)  DEFAULT '' COMMENT '更新者',
  `update_time`   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='快递公司表';
DROP TABLE IF EXISTS `trade_delivery_express_template`;
CREATE TABLE `trade_delivery_express_template` (
  `id`            bigint      NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name`          varchar(64) NOT NULL COMMENT '模板名称',
  `charge_mode`   tinyint     NOT NULL COMMENT '计费方式：1 按件 2 按重量 3 按体积',
  `sort`          int         NOT NULL DEFAULT 0 COMMENT '排序',
  `tenant_id`     bigint      NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`       varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time`   datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`       varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time`   datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       bit(1)      NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='运费模板表';
DROP TABLE IF EXISTS `trade_delivery_express_template_charge`;
CREATE TABLE `trade_delivery_express_template_charge` (
  `id`            bigint        NOT NULL AUTO_INCREMENT COMMENT '编号',
  `template_id`   bigint        NOT NULL COMMENT '运费模板编号',
  `area_ids`      varchar(2000) NOT NULL COMMENT '配送区域编号数组',
  `charge_mode`   tinyint       NOT NULL COMMENT '计费方式，冗余',
  `start_count`   double        NOT NULL COMMENT '首件数量',
  `start_price`   int           NOT NULL DEFAULT 0 COMMENT '起步价，单位：分',
  `extra_count`   double        NOT NULL COMMENT '续件数量',
  `extra_price`   int           NOT NULL DEFAULT 0 COMMENT '额外价，单位：分',
  `tenant_id`     bigint        NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`       varchar(64)   DEFAULT '' COMMENT '创建者',
  `create_time`   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`       varchar(64)   DEFAULT '' COMMENT '更新者',
  `update_time`   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       bit(1)        NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_template_id` (`template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='运费模板计费配置表';
DROP TABLE IF EXISTS `trade_delivery_express_template_free`;
CREATE TABLE `trade_delivery_express_template_free` (
  `id`            bigint        NOT NULL AUTO_INCREMENT COMMENT '编号',
  `template_id`   bigint        NOT NULL COMMENT '运费模板编号',
  `area_ids`      varchar(2000) NOT NULL COMMENT '包邮区域编号数组',
  `free_price`    int           NOT NULL DEFAULT 0 COMMENT '包邮金额，单位：分',
  `free_count`    int           NOT NULL DEFAULT 0 COMMENT '包邮件数',
  `tenant_id`     bigint        NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`       varchar(64)   DEFAULT '' COMMENT '创建者',
  `create_time`   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`       varchar(64)   DEFAULT '' COMMENT '更新者',
  `update_time`   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       bit(1)        NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_template_id` (`template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='运费模板包邮配置表';
DROP TABLE IF EXISTS `trade_delivery_pick_up_store`;
CREATE TABLE `trade_delivery_pick_up_store` (
  `id`                bigint       NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name`              varchar(64)  NOT NULL COMMENT '门店名称',
  `introduction`      varchar(256) DEFAULT '' COMMENT '门店简介',
  `phone`             varchar(16)  NOT NULL COMMENT '门店手机',
  `area_id`           int          NOT NULL COMMENT '区域编号',
  `detail_address`    varchar(256) NOT NULL COMMENT '门店详细地址',
  `logo`              varchar(256) NOT NULL COMMENT '门店 logo',
  `opening_time`      time         NOT NULL COMMENT '营业开始时间',
  `closing_time`      time         NOT NULL COMMENT '营业结束时间',
  `latitude`          double       NOT NULL COMMENT '纬度',
  `longitude`         double       NOT NULL COMMENT '经度',
  `verify_user_ids`   varchar(256) DEFAULT NULL COMMENT '核销员工用户编号数组',
  `status`            tinyint      NOT NULL DEFAULT 0 COMMENT '状态：0 开启 1 关闭',
  `sort`              int          NOT NULL DEFAULT 0 COMMENT '排序',
  `tenant_id`         bigint       NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`           varchar(64)  DEFAULT '' COMMENT '创建者',
  `create_time`       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`           varchar(64)  DEFAULT '' COMMENT '更新者',
  `update_time`       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`           bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='自提门店表';

-- ========================= 分销 =========================

DROP TABLE IF EXISTS `trade_brokerage_user`;
CREATE TABLE `trade_brokerage_user` (
  `id`                  bigint      NOT NULL COMMENT '用户编号',
  `bind_user_id`        bigint      DEFAULT NULL COMMENT '推广员编号，即上级',
  `bind_user_time`      datetime    DEFAULT NULL COMMENT '推广员绑定时间',
  `brokerage_enabled`   bit(1)      NOT NULL DEFAULT b'1' COMMENT '是否有分销资格',
  `brokerage_time`      datetime    DEFAULT NULL COMMENT '成为分销员时间',
  `brokerage_price`     int         NOT NULL DEFAULT 0 COMMENT '可用佣金，单位：分',
  `frozen_price`        int         NOT NULL DEFAULT 0 COMMENT '冻结佣金，单位：分',
  `tenant_id`           bigint      NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`             varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time`         datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`             varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time`         datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`             bit(1)      NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_bind_user_id` (`bind_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分销用户表';
DROP TABLE IF EXISTS `trade_brokerage_record`;
CREATE TABLE `trade_brokerage_record` (
  `id`                  bigint       NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id`             bigint       NOT NULL COMMENT '用户编号',
  `biz_id`              varchar(64)  NOT NULL COMMENT '业务编号，如订单项编号',
  `biz_type`            tinyint      NOT NULL COMMENT '业务类型：1 订单返佣 2 提现申请 3 提现驳回',
  `title`               varchar(64)  NOT NULL COMMENT '标题',
  `price`               int          NOT NULL COMMENT '变动金额，单位分',
  `total_price`         int          NOT NULL COMMENT '变动后当前总佣金，单位分',
  `description`         varchar(500) NOT NULL DEFAULT '' COMMENT '说明',
  `status`              tinyint      NOT NULL COMMENT '状态：0 待结算 1 已结算 2 已取消',
  `frozen_days`         int          NOT NULL DEFAULT 0 COMMENT '冻结时间，单位天',
  `unfreeze_time`       datetime     DEFAULT NULL COMMENT '解冻时间',
  `source_user_level`   tinyint      NOT NULL COMMENT '来源用户等级：1 直推 2 间推',
  `source_user_id`      bigint       NOT NULL COMMENT '来源用户编号',
  `tenant_id`           bigint       NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`             varchar(64)  DEFAULT '' COMMENT '创建者',
  `create_time`         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`             varchar(64)  DEFAULT '' COMMENT '更新者',
  `update_time`         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`             bit(1)       NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  UNIQUE KEY `uk_user_biz` (`user_id`, `biz_type`, `biz_id`, `deleted`),
  KEY `idx_status_unfreeze` (`status`, `unfreeze_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='佣金记录表。同一业务单据给同一用户只结算一次';
DROP TABLE IF EXISTS `trade_brokerage_withdraw`;
CREATE TABLE `trade_brokerage_withdraw` (
  `id`                      bigint        NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id`                 bigint        NOT NULL COMMENT '用户编号',
  `price`                   int           NOT NULL DEFAULT 0 COMMENT '提现金额，单位：分',
  `fee_price`               int           NOT NULL DEFAULT 0 COMMENT '提现手续费，单位：分',
  `total_price`             int           NOT NULL DEFAULT 0 COMMENT '当前总佣金，单位：分',
  `type`                    tinyint       NOT NULL COMMENT '提现类型：1 钱包 2 银行卡 3 微信 4 支付宝',
  `user_name`               varchar(64)   DEFAULT NULL COMMENT '真实姓名',
  `user_account`            varchar(128)  DEFAULT NULL COMMENT '账号',
  `qr_code_url`             varchar(512)  DEFAULT NULL COMMENT '收款码',
  `bank_name`               varchar(100)  DEFAULT NULL COMMENT '银行名称',
  `bank_address`            varchar(200)  DEFAULT NULL COMMENT '开户地址',
  `status`                  tinyint       NOT NULL COMMENT '状态：0 审核中 10 审核通过 20 提现成功 21 提现失败 30 审核不通过',
  `audit_reason`            varchar(128)  DEFAULT NULL COMMENT '审核驳回原因',
  `audit_time`              datetime      DEFAULT NULL COMMENT '审核时间',
  `remark`                  varchar(500)  DEFAULT NULL COMMENT '备注',
  `pay_transfer_id`         bigint        DEFAULT NULL COMMENT '转账单编号',
  `transfer_channel_code`   varchar(32)   DEFAULT NULL COMMENT '转账渠道',
  `transfer_time`           datetime      DEFAULT NULL COMMENT '转账成功时间',
  `transfer_error_msg`      varchar(4096) DEFAULT NULL COMMENT '转账错误提示',
  `tenant_id`               bigint        NOT NULL DEFAULT 0 COMMENT '租户编号',
  `creator`                 varchar(64)   DEFAULT '' COMMENT '创建者',
  `create_time`             datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater`                 varchar(64)   DEFAULT '' COMMENT '更新者',
  `update_time`             datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`                 bit(1)        NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='佣金提现表';

