-- ----------------------------------------------------------------------------
USE `ccloud`;

-- ========================= 内容 =========================

DROP TABLE IF EXISTS `promotion_banner`;
CREATE TABLE `promotion_banner` (
  `id`             bigint       NOT NULL AUTO_INCREMENT COMMENT '编号',
